package com.estoqueinteligente.supplier;import jakarta.validation.constraints.*;public class SupplierRequest{@NotBlank(message="O nome é obrigatório")@Size(max=150)private String name;@Size(max=30)private String phone;@Email(message="O e-mail deve ter formato válido")@Size(max=150)private String email;@Size(max=120)private String contactPerson;private String notes;public SupplierRequest(){}public String getName(){return name;}public void setName(String v){name=v;}public String getPhone(){return phone;}public void setPhone(String v){phone=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getContactPerson(){return contactPerson;}public void setContactPerson(String v){contactPerson=v;}public String getNotes(){return notes;}public void setNotes(String v){notes=v;}}
